bool ScenarioSelectorNode::isAutonomous() const
{
  return operation_mode_state_->mode ==
           autoware_adapi_v1_msgs::msg::OperationModeState::AUTONOMOUS &&
         operation_mode_state_->is_autoware_control_enabled;
}
